#kills b{font-size:28px;color:#e9e4d6;font-weight:700;line-height:1}
#kills span{font-size:9px;letter-spacing:.3em;color:#8f9a9d;font-weight:700}

#prompt{position:absolute;left:50%;top:58%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:12px;
  padding:10px 18px 10px 10px;background:rgba(6,9,11,.72);border:1px solid rgba(255,255,255,.2);
  box-shadow:0 0 40px rgba(0,0,0,.6);animation:promptIn .18s ease-out}
#prompt .key{width:34px;height:34px;display:grid;place-items:center;border:1px solid rgba(232,227,215,.75);
  font-size:16px;font-weight:700;color:#f3efe4;background:rgba(255,255,255,.06)}
#prompt .ptext{font-size:13px;letter-spacing:.34em;color:#f3efe4;font-weight:700;text-indent:.34em}
@keyframes promptIn{from{opacity:0;transform:translate(-50%,-46%)}to{opacity:1;transform:translate(-50%,-50%)}}

#subtitle{position:absolute;left:50%;bottom:16%;transform:translateX(-50%);font-size:13px;letter-spacing:.22em;
  color:#d6d1c4;text-shadow:0 2px 8px #000;text-align:center;opacity:0;transition:opacity .4s;font-weight:600;max-width:70vw}
#subtitle.on{opacity:1}

#crosshair{position:absolute;left:50%;top:50%;width:22px;height:22px;transform:translate(-50%,-50%);z-index:8;pointer-events:none;opacity:.65}
#crosshair i{position:absolute;background:rgba(232,227,215,.85);box-shadow:0 0 3px #000}
#crosshair i:nth-child(1){width:1px;height:5px;left:10.5px;top:0}
#crosshair i:nth-child(2){width:1px;height:5px;left:10.5px;bottom:0}
#crosshair i:nth-child(3){width:5px;height:1px;top:10.5px;left:0}
#crosshair i:nth-child(4){width:5px;height:1px;top:10.5px;right:0}
#crosshair b{position:absolute;width:2px;height:2px;background:rgba(232,227,215,.9);left:10px;top:10px;border-radius:50%}

/* ---------- title ---------- */
#titleScreen{position:absolute;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;
  background:radial-gradient(ellipse at 28% 45%,rgba(4,6,8,.22) 0%,rgba(3,5,7,.74) 55%,rgba(2,3,5,.96) 100%);
  transition:opacity .9s ease}
#titleScreen.gone{opacity:0;pointer-events:none}
.title-bg{position:absolute;inset:0;background:
  linear-gradient(90deg,rgba(3,5,7,.92) 0%,rgba(3,5,7,.6) 38%,rgba(3,5,7,0) 70%),
  repeating-linear-gradient(0deg,rgba(255,255,255,.018) 0 1px,transparent 1px 3px);pointer-events:none}
.title-content{position:relative;margin-left:min(11vw,150px);max-width:600px;padding:24px}
.eyebrow{font-size:10px;letter-spacing:.5em;color:#8b979a;font-weight:700;margin-bottom:14px;text-indent:.5em}
.logo{font-size:clamp(58px,9vw,124px);line-height:.82;letter-spacing:.015em;font-weight:900;color:#eee9dc;
  text-transform:uppercase;text-shadow:0 4px 0 #1a1d1e,0 14px 40px rgba(0,0,0,.9);
  transform:scaleX(.86);transform-origin:left center;white-space:nowrap}
.logo span{position:relative;display:inline-block}
.logo span:after{content:"";position:absolute;left:2%;right:-1%;bottom:-9px;height:3px;
  background:linear-gradient(90deg,var(--blood),rgba(179,18,27,0));box-shadow:0 0 18px rgba(179,18,27,.5)}
.tagline{margin-top:18px;font-size:clamp(16px,2vw,24px);letter-spacing:.72em;color:#b7bfbe;font-weight:700;text-indent:.72em}
.blurb{margin-top:30px;font-size:14px;line-height:1.85;color:#9ca5a6;letter-spacing:.045em;max-width:460px;font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;font-weight:400}
#playBtn{margin-top:34px;position:relative;padding:16px 64px 15px 64px;background:rgba(179,18,27,.92);color:#f5f0e4;
  border:0;font-family:inherit;font-size:16px;letter-spacing:.42em;text-indent:.42em;font-weight:700;cursor:pointer;
  transform:skewX(-10deg);box-shadow:0 10px 40px rgba(179,18,27,.35),inset 0 0 0 1px rgba(255,255,255,.18);
  transition:background .2s,transform .2s,box-shadow .2s}
#playBtn:hover{background:#d41a25;transform:skewX(-10deg) translateY(-2px);box-shadow:0 16px 50px rgba(200,20,30,.5),inset 0 0 0 1px rgba(255,255,255,.3)}
#playBtn:active{transform:skewX(-10deg) translateY(1px)}
.controls{margin-top:38px;display:flex;flex-wrap:wrap;gap:10px 26px;max-width:520px}
.controls div{display:flex;align-items:center;gap:9px}
kbd{font-family:inherit;font-size:9px;letter-spacing:.16em;color:#c7cfcd;border:1px solid rgba(160,175,178,.32);
  padding:5px 7px;background:rgba(255,255,255,.035);font-weight:700}
.controls span{font-size:9px;letter-spacing:.26em;color:#6e797c;font-weight:700}
.finePrint{margin-top:26px;font-size:9px;letter-spacing:.22em;color:#4f5a5d;text-transform:uppercase;font-weight:600}

/* ---------- overlays ---------- */
.overlay{position:absolute;inset:0;z-index:25;display:flex;align-items:center;justify-content:center;
  background:radial-gradient(ellipse at center,rgba(20,0,0,.55),rgba(2,3,4,.94));backdrop-filter:blur(5px);
  animation:ovIn .5s ease}
@keyframes ovIn{from{opacity:0}to{opacity:1}}
.ov-inner{text-align:center;max-width:680px;padding:30px}
.ov-kicker{font-size:10px;letter-spacing:.5em;color:#8d1c22;font-weight:700;margin-bottom:16px;text-indent:.5em}
h2{font-size:clamp(38px,6vw,74px);letter-spacing:.06em;font-weight:900;text-transform:uppercase;transform:scaleX(.9)}
h2.dead{color:#cf2028;text-shadow:0 0 60px rgba(179,18,27,.5),0 6px 0 #2a0b0d}
h2.win{color:#dce0cd;text-shadow:0 0 70px rgba(190,220,150,.2),0 6px 0 #1a1f17}
.overlay p{margin-top:18px;font-size:13px;letter-spacing:.16em;color:#99a2a2;line-height:1.8}
.restart,#resumeBtn{margin-top:34px;padding:14px 52px;background:transparent;color:#e6e0d3;border:1px solid rgba(230,224,211,.45);
  font-family:inherit;font-size:13px;letter-spacing:.4em;text-indent:.4em;font-weight:700;cursor:pointer;transition:.2s}
.restart:hover,#resumeBtn:hover{background:#e6e0d3;color:#0a0c0d}
.stats{display:flex;justify-content:center;gap:52px;margin-top:34px}
.stats div{display:flex;flex-direction:column;gap:8px}
.stats b{font-size:32px;letter-spacing:.04em;color:#e9e4d6;font-weight:700}
.stats span{font-size:9px;letter-spacing:.32em;color:#7f8a8c;font-weight:700}

/* ---------- loading ---------- */
#loading{position:absolute;inset:0;z-index:40;background:#05070a;display:flex;align-items:center;justify-content:center;transition:opacity .6s}
#loading.gone{opacity:0;pointer-events:none}
.load-inner{text-align:center}
.load-logo{font-size:28px;letter-spacing:.55em;font-weight:900;color:#ddd8cb;text-indent:.55em;transform:scaleX(.9)}
.load-bar{width:220px;height:2px;background:rgba(255,255,255,.1);margin:26px auto 14px;overflow:hidden}
.load-bar i{display:block;height:100%;width:40%;background:#b3121b;animation:loadSlide 1.1s infinite ease-in-out}
@keyframes loadSlide{0%{transform:translateX(-110%)}100%{transform:translateX(300%)}}
.load-text{font-size:9px;letter-spacing:.4em;color:#657074;font-weight:700}

/* ---------- mobile ---------- */
#mobile{position:absolute;inset:0;z-index:12;pointer-events:none;display:none}
#mobile.on{display:block}
#stick{position:absolute;left:max(26px,env(safe-area-inset-left));bottom:max(92px,calc(env(safe-area-inset-bottom) + 84px));width:132px;height:132px;
  border-radius:50%;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.035);pointer-events:auto;touch-action:none}
#stickNub{position:absolute;left:50%;top:50%;width:54px;height:54px;margin:-27px 0 0 -27px;border-radius:50%;
  background:rgba(230,225,212,.22);border:1px solid rgba(255,255,255,.3);box-shadow:0 0 24px rgba(0,0,0,.5)}
#mBtns{position:absolute;right:max(22px,env(safe-area-inset-right));bottom:max(92px,calc(env(safe-area-inset-bottom) + 84px));
  display:flex;flex-direction:column;align-items:flex-end;gap:14px;pointer-events:auto}
.mbtn{width:92px;height:92px;border-radius:50%;border:1px solid rgba(255,255,255,.24);background:rgba(179,18,27,.45);
  color:#f2ede1;font-family:inherit;font-size:11px;letter-spacing:.13em;font-weight:700;backdrop-filter:blur(2px);touch-action:none}
.mbtn.small{width:66px;height:66px;font-size:9px;background:rgba(255,255,255,.09)}
.mbtn:active{background:rgba(220,30,40,.75)}
.mbtn.exec{border-color:rgba(255,255,255,.7);box-shadow:0 0 30px rgba(220,40,40,.45);animation:execPulse 1.3s infinite}
@keyframes execPulse{0%,100%{box-shadow:0 0 18px rgba(220,40,40,.25)}50%{box-shadow:0 0 36px rgba(220,40,40,.65)}}

@media (max-width:760px){
  #objective{max-width:230px}
  #objText{font-size:13px;letter-spacing:.1em}
  #objSub{font-size:9px}
  #minimapWrap{width:112px;height:112px}
  #detect{top:auto;bottom:calc(env(safe-area-inset-bottom) + 20px);width:120px}
  #detectText{display:none}
  #vitals{width:180px;bottom:calc(env(safe-area-inset-bottom) + 18px)}
  #weaponCard{display:none}
  #kills{bottom:auto;top:calc(env(safe-area-inset-top) + 122px);left:auto;right:max(22px,env(safe-area-inset-right));transform:none}
  #kills b{font-size:20px}
  #kills span{display:none}
  .title-content{margin-left:0;padding:26px;max-width:100%}
  .controls{gap:8px 14px}
  .blurb{font-size:12px;line-height:1.6;margin-top:20px}
  #playBtn{padding:14px 48px}
  .tagline{letter-spacing:.5em}
  #prompt{top:50%}
  .stats{gap:26px}
}
@media (max-height:520px){
  .controls,.finePrint,.blurb{display:none}
  .logo{font-size:52px}
  #playBtn{margin-top:18px}
}

import * as THREE from 'three';

// NIGHTFALL — a compact, atmospheric stealth game. Takedowns are deliberately implied.
const canvas = document.querySelector('#scene');
