mat('steel',0x252d30,.54,.55); mat('black',0x111618,.68,.2); mat('yellow',0x948044,.82); mat('canvas',0x3b443b,.98);
mat('skin',0x988577,.82); mat('uniform',0x26312f,.88); mat('vest',0x171f20,.78); mat('boots',0x111515,.8);
