const world = new THREE.Group(); scene.add(world);
const hemi = new THREE.HemisphereLight(0x8798a0,0x151713,1.3); scene.add(hemi);
const moon = new THREE.DirectionalLight(0xa6c0d0,2.1); moon.position.set(-18,30,17); moon.castShadow=true; moon.shadow.mapSize.set(2048,2048); moon.shadow.camera.left=-55; moon.shadow.camera.right=55; moon.shadow.camera.top=55; moon.shadow.camera.bottom=-55; moon.shadow.bias=-.0003; scene.add(moon);
