// Wet industrial freight yard, assembled from worn modular shapes.
plane(world,0,-.12,0,100,100,mats.ground);
// Broken tarmac slabs and reflective puddles.
for(let i=0;i<38;i++){const x=(Math.random()-.5)*68,z=(Math.random()-.5)*70;if(Math.abs(x)<4&&Math.abs(z)<5)continue;
 const p=plane(world,x,-.095+Math.random()*.006,z,1+Math.random()*5,.5+Math.random()*2,mats.water);p.rotation.z=Math.random()*Math.PI;}
