// Perimeter warehouse walls
function wall(x,z,w,h,depth=1){box(world,x,h/2,z,w,h,depth,mats.concrete);for(let y=1;y<h;y+=2.6)box(world,x,y,z-depth*.51,w,.055,.05,mats.steel,false);}
wall(0,-38,76,13); wall(-38,0,1,13,76); wall(38,0,1,13,76); wall(0,38,76,13);
// North exit gate
box(world,-5,2.6,-37.4,.22,5.2,.25,mats.steel);box(world,5,2.6,-37.4,.22,5.2,.25,mats.steel);box(world,0,5.15,-37.4,10,.22,.25,mats.steel);
for(let x=-4.5;x<=4.5;x+=.55)box(world,x,2.5,-37.4,.07,5,.08,mats.steel);
const exitGlow=new THREE.Mesh(new THREE.PlaneGeometry(8,4),new THREE.MeshBasicMaterial({color:0x9cae8c,transparent:true,opacity:.16,side:THREE.DoubleSide}));exitGlow.position.set(0,2,-37.25);world.add(exitGlow);
