 for(const xx of [-w/2+.1,w/2-.1])box(group,xx,h/2,d/2+.06,.14,h,.14,mats.steel);
 for(const yy of [.18,h-.18])box(group,0,yy,d/2+.065,w,.14,.12,mats.steel);
