 for(let i=0;i<3;i++)box(world,x-1+i,.12,z+.62,.04,.17,.04,mats.yellow,false);
}
for(const [x,z] of [[-11,1],[12,0],[-29,-27],[29,-28]]){
 cylinder(world,x,.55,z,.9,.9,1.1,mats.rust);cylinder(world,x,.57,z,.95,.95,.08,mats.steel);cylinder(world,x,.58,z,.5,.5,.09,mats.black);
}
// Lamp poles and haze pools.
for(const [x,z] of [[-30,-2],[30,-1],[-4,-33],[4,32],[-32,30],[32,29]]){
 cylinder(world,x,5,z,.12,.17,10,mats.black,10);box(world,x,10,z,.8,.18,.35,mats.steel);
 const bulb=new THREE.Mesh(new THREE.SphereGeometry(.14,8,8),new THREE.MeshBasicMaterial({color:0xffd69a}));bulb.position.set(x,9.82,z);world.add(bulb);
 const l=pointLight([x,9.5,z],0xffbd73,23,20);l.position.x=x;l.position.z=z;
