// Guard models and simple state-driven patrol / investigate / chase behavior.
const guards=[];
const routes=[
 [[-29,-25],[-8,-24],[-8,-14],[-28,-13]], [[25,-27],[7,-26],[7,-18],[25,-17]],
 [[-29,9],[-8,9],[-8,17],[-28,17]], [[29,9],[8,9],[8,18],[29,18]],
