];
function makeGuard(idx,pos){const g=new THREE.Group();world.add(g);g.position.set(pos[0],0,pos[1]);
 const tunic=new THREE.Mesh(new THREE.CapsuleGeometry(.29,.82,4,8),mats.uniform);tunic.position.y=1.1;tunic.castShadow=true;g.add(tunic);
 const vest=new THREE.Mesh(new THREE.BoxGeometry(.48,.52,.28),mats.vest);vest.position.set(0,1.17,-.02);vest.castShadow=true;g.add(vest);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.22,12,10),mats.skin);head.position.y=1.88;head.castShadow=true;g.add(head);
 const helmet=new THREE.Mesh(new THREE.SphereGeometry(.25,12,7,0,Math.PI*2,0,Math.PI*.56),mats.black);helmet.position.y=2.02;helmet.castShadow=true;g.add(helmet);
 const visor=new THREE.Mesh(new THREE.BoxGeometry(.29,.085,.12),new THREE.MeshStandardMaterial({color:0x11191b,metalness:.3,roughness:.22,emissive:0x18272a,emissiveIntensity:.3}));visor.position.set(0,1.96,-.19);g.add(visor);
 for(const side of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.105,.62,3,6),mats.black);leg.position.set(side*.14,.4,0);leg.castShadow=true;g.add(leg);}
 for(const side of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.09,.49,3,6),mats.uniform);arm.position.set(side*.37,1.2,-.01);arm.rotation.z=side*.16;g.add(arm);}
